using Captovix;
int n=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;Console.WriteLine("PASS: "+name);}
byte[] bytes=new byte[40*30*4];for(int i=0;i<bytes.Length;i+=4){bytes[i]=32;bytes[i+1]=48;bytes[i+2]=64;bytes[i+3]=255;}var original=bytes.ToArray();
var sample=AssistedPixels.Sample(bytes,40,30,new(2,3,32,22));Check(sample.Color=="#403020"&&sample.Spread==0,"Uniform background sampled exactly");Check(bytes.SequenceEqual(original),"Sampling never edits source pixels");
for(int i=3;i<bytes.Length;i+=4)bytes[i]=0;Check(AssistedPixels.Sample(bytes,40,30,new(0,0,40,30)).Color=="#FFFFFF","Transparent source composited over white for sampling");
for(int y=0;y<30;y++)for(int x=0;x<40;x++){int i=(y*40+x)*4;bytes[i]=bytes[i+1]=bytes[i+2]=(byte)(x%2==0?0:255);bytes[i+3]=255;}Check(AssistedPixels.Sample(bytes,40,30,new(0,0,40,30)).Spread>18,"Nonuniform edges trigger uncertain-background signal");
foreach(var r in new[]{new PixelRect(-1,0,20,20),new(30,0,20,20),new(0,0,1,1)}){bool bad=false;try{AssistedPixels.Sample(bytes,40,30,r);}catch(ArgumentException){bad=true;}Check(bad,"Invalid sample region rejected");}
var notice=new UpdatePromptPolicy();Check(!notice.Offer("1.18.0",true,true),"Busy capture delays notification");Check(notice.Offer("1.18.0",true,false),"Notification offered after busy state ends");Check(!notice.Offer("1.18.0",true,false),"Same version never repeats in a session");Check(notice.Offer("1.19.0",true,false),"A newer release can notify");Check(!notice.Offer(null,true,false)&&!notice.Offer("1.20.0",false,false),"No notification for absent/unavailable release");notice.Release("1.19.0");Check(notice.Offer("1.19.0",true,false),"Queued notification can retry after a new blocking operation");
var window=new PixelRect(-1500,-100,1200,900);var grid=new PixelRect(-1400,0,400,300);var leaf=new PixelRect(-1380,20,40,20);var chain=ElementSelection.Normalize([new(window,"window",true),new(grid,"grid",true),new(leaf,"leaf")],-1370,25,window);Check(chain.Length==3&&chain[ElementSelection.Preferred(chain)].Bounds==grid,"Unsorted provider candidates normalize leaf to parent");var duplicated=ElementSelection.Normalize([new(grid,"raw leaf"),new(grid,"container",true)],-1370,25,window);Check(duplicated[0].Container,"Duplicate bounds retain container semantics");
string root=Path.Combine(Path.GetTempPath(),"Captovix-117-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
try{
 string data=Path.Combine(root,"data"),media=Path.Combine(root,"ảnh-media");Check(MediaLocation.Load(data)==Path.Combine(data,"Media"),"No preference uses default media folder");string selected=MediaLocation.Validate(media);MediaLocation.Save(data,selected);Check(MediaLocation.Load(data)==selected,"Custom media folder survives reload");Check(!Directory.EnumerateFiles(media).Any(),"Write probe is removed");File.WriteAllText(Path.Combine(media,"existing.png"),"unchanged");MediaLocation.Validate(media);Check(File.ReadAllText(Path.Combine(media,"existing.png"))=="unchanged","Selecting storage preserves old files");Check(!Directory.EnumerateFiles(data,"*.tmp").Any(),"Config commit leaves no temporary file");File.WriteAllText(Path.Combine(data,MediaLocation.FileName),"broken");bool corrupt=false;try{MediaLocation.Load(data);}catch(System.Text.Json.JsonException){corrupt=true;}Check(corrupt&&File.ReadAllText(Path.Combine(data,MediaLocation.FileName))=="broken","Corrupt path configuration is reported and preserved");bool relative=false;try{MediaLocation.Validate("relative-folder");}catch(ArgumentException){relative=true;}Check(relative,"Relative media paths rejected");
 Check(BrandOwnership.IsOwned(root,Path.Combine(root,"Update.exe")),"Owned updater shortcut accepted");Check(BrandOwnership.IsOwned(root,Path.Combine(root,"current","Captovix.exe")),"Owned app shortcut accepted");Check(!BrandOwnership.IsOwned(root,Path.Combine(root+"-other","Captovix.exe")),"Similar directory name is not owned");Check(!BrandOwnership.IsOwned(root,Path.Combine(root,"Other.exe")),"Other app shortcut never rewritten");Check(!BrandOwnership.IsOwned(root,Path.Combine(root,"sub","Update.exe")),"Nested unrelated updater never rewritten");Check(!BrandOwnership.IsOwned(root,"relative.exe"),"Relative shortcut target never rewritten");
}finally{Directory.Delete(root,true);}
